const normalize=(path)=>String(path??'').replace(/^\/+/, '');
const clone=(value)=>value==null?value:structuredClone(value);
const key=(namespace,path)=>`${namespace}:${normalize(path)}`;
const requestResult=(request)=>new Promise((resolve,reject)=>{request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error??new Error('IndexedDB request failed.'));});
const txDone=(tx)=>new Promise((resolve,reject)=>{tx.oncomplete=()=>resolve();tx.onabort=()=>reject(tx.error??new Error('IndexedDB transaction aborted.'));tx.onerror=()=>reject(tx.error??new Error('IndexedDB transaction failed.'));});
export class MemoryStorage {#data=new Map();async put(path,value,options={}){const normalized=normalize(path);if(!normalized)throw new TypeError('path is required.');this.#data.set(normalized,{value:clone(value),metadata:clone(options.metadata??{})});return{path:normalized};}async get(path){const found=this.#data.get(normalize(path));return found?{value:clone(found.value),metadata:clone(found.metadata)}:null;}async delete(path){return this.#data.delete(normalize(path));}async list(prefix=''){const normalized=normalize(prefix);return [...this.#data.keys()].filter(path=>path.startsWith(normalized)).sort();}async health(){return{ok:true,driver:'memory-browser'};}async close(){}}
export class IndexedDbStorage {#factory;#dbName;#storeName;#version;#dbPromise=null;constructor({indexedDB=globalThis.indexedDB,dbName='artisys-storage',storeName='entries',version=1}={}){if(!indexedDB||typeof indexedDB.open!=='function')throw new TypeError('IndexedDB is required.');this.#factory=indexedDB;this.#dbName=String(dbName);this.#storeName=String(storeName);this.#version=Number(version);}async #db(){if(!this.#dbPromise)this.#dbPromise=new Promise((resolve,reject)=>{const request=this.#factory.open(this.#dbName,this.#version);request.onupgradeneeded=()=>{const db=request.result;if(!db.objectStoreNames.contains(this.#storeName))db.createObjectStore(this.#storeName);};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error??new Error('Unable to open IndexedDB.'));request.onblocked=()=>reject(new Error('IndexedDB upgrade is blocked.'));});return this.#dbPromise;}async put(path,value,options={}){const normalized=normalize(path);if(!normalized)throw new TypeError('path is required.');const db=await this.#db();const tx=db.transaction(this.#storeName,'readwrite');const done=txDone(tx);tx.objectStore(this.#storeName).put({value:clone(value),metadata:clone(options.metadata??{}),updatedAt:new Date().toISOString()},normalized);await done;return{path:normalized};}async get(path){const db=await this.#db();const tx=db.transaction(this.#storeName,'readonly');const done=txDone(tx);const value=await requestResult(tx.objectStore(this.#storeName).get(normalize(path)));await done;return value?{value:clone(value.value),metadata:clone(value.metadata??{})}:null;}async delete(path){const db=await this.#db();const normalized=normalize(path);const existing=await this.get(normalized);if(!existing)return false;const tx=db.transaction(this.#storeName,'readwrite');const done=txDone(tx);tx.objectStore(this.#storeName).delete(normalized);await done;return true;}async list(prefix=''){const db=await this.#db();const tx=db.transaction(this.#storeName,'readonly');const done=txDone(tx);const store=tx.objectStore(this.#storeName);let keys;if(typeof store.getAllKeys==='function')keys=await requestResult(store.getAllKeys());else keys=await new Promise((resolve,reject)=>{const out=[];const request=store.openKeyCursor();request.onsuccess=()=>{const cursor=request.result;if(!cursor){resolve(out);return;}out.push(cursor.key);cursor.continue();};request.onerror=()=>reject(request.error??new Error('Unable to list IndexedDB keys.'));});await done;const normalized=normalize(prefix);return keys.map(String).filter(path=>path.startsWith(normalized)).sort();}async health(){const db=await this.#db();return{ok:Boolean(db),driver:'indexeddb',dbName:this.#dbName};}async close(){if(this.#dbPromise){const db=await this.#dbPromise;db.close();this.#dbPromise=null;}}}
export function namespaceStorage(storage,namespace){if(!storage||!namespace)throw new TypeError('storage and namespace are required');return{put:(path,value,options)=>storage.put(key(namespace,path),value,options),get:path=>storage.get(key(namespace,path)),delete:path=>storage.delete(key(namespace,path)),list:async(prefix='')=>(await storage.list(`${namespace}:${normalize(prefix)}`)).map(path=>path.slice(namespace.length+1)),health:()=>storage.health?.(),close:()=>storage.close?.()};}